import * as React from "react";

export type TicketPerforationIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function TicketPerforationIcon({ size = 20, ...props }: TicketPerforationIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="7" width="16" height="10" rx="1.5" /><circle cx="8" cy="12" r="1" /><circle cx="12" cy="12" r="1" /><circle cx="16" cy="12" r="1" />
    </svg>
  );
}
